<script setup lang="ts">
import {useProductivityStore} from '~/stores/productivity'; const store=useProductivityStore(); const days=store.last7Days; const vals=store.weeklyFocusMinutes; const max=Math.max(1,...vals); const total=computed(()=>vals.reduce((a,b)=>a+b,0)); const completedToday=computed(()=>store.tasksToday.filter(t=>t.status==='completed').length); const plannedToday=computed(()=>store.tasksToday.length); const insights=computed(()=>{const x:string[]=[]; if(total.value) x.push(`در ۷ روز اخیر ${total.value} دقیقه تمرکز ثبت شده.`); if(store.planningAccuracy<75&&store.planningAccuracy>0)x.push('تخمین زمان کارهایت کمی خوش‌بینانه است؛ برای کارهای مشابه زمان واقعی را معیار قرار بده.'); if(store.taskCompletionRate>=80)x.push('نرخ اجرای کارها عالی است؛ می‌توانی برنامه‌های روزانه را کمی دقیق‌تر بچینی.'); if(store.consistencyScore<60)x.push('ثبات مهم‌ترین فرصت رشد توست؛ حتی یک جلسه کوتاه در روز بهتر از وقفه‌های طولانی است.'); if(!x.length)x.push('با چند جلسه و چند روز داده، تحلیل شخصی‌سازی‌شده‌تری ساخته می‌شود.'); return x})
</script>
<template><div class="space-y-6"><div><h1 class="text-3xl font-black">تحلیل هوشمند عملکرد</h1><p class="text-gray-500">شاخص‌ها از برنامه، اجرای واقعی، تایمر و گزارش‌ها ساخته می‌شوند.</p></div><div class="grid sm:grid-cols-2 xl:grid-cols-5 gap-3"><UCard v-for="x in [{l:'امتیاز کلی',v:store.performanceScore.total},{l:'ثبات',v:store.consistencyScore},{l:'اجرای کارها',v:store.taskCompletionRate},{l:'دقت تخمین',v:store.planningAccuracy},{l:'پیشرفت اهداف',v:store.goalProgressAverage}]" :key="x.l"><p class="text-xs text-gray-500">{{x.l}}</p><b class="text-3xl mt-2 block">{{x.v}}<span class="text-sm">٪</span></b><UProgress :model-value="x.v" class="mt-3"/></UCard></div><div class="grid xl:grid-cols-3 gap-4"><UCard class="xl:col-span-2"><template #header><div class="flex justify-between"><b>تمرکز ۷ روز اخیر</b><UBadge variant="soft">{{total}} دقیقه</UBadge></div></template><div class="h-72 flex items-end gap-3"><div v-for="(v,i) in vals" :key="days[i]" class="flex-1 h-full flex flex-col justify-end items-center gap-2"><div class="w-full rounded-t-xl bg-primary-500/80" :style="{height:`${Math.max(4,v/max*100)}%`}"/><span class="text-xs text-gray-500">{{new Date(days[i]+'T12:00').toLocaleDateString('fa-IR',{weekday:'short'})}}</span><span class="text-xs">{{v}}د</span></div></div></UCard><UCard><template #header>بینش‌های پیشنهادی</template><div class="space-y-3"><UAlert v-for="(x,i) in insights" :key="i" color="primary" variant="soft" :description="x" icon="i-lucide-sparkles"/></div></UCard></div><UCard><template #header>جزئیات داده</template><div class="grid md:grid-cols-4 gap-3 text-center"><div class="p-4 rounded-2xl bg-gray-50 dark:bg-gray-800/60"><b>{{store.focusLogs.length}}</b><p class="text-xs text-gray-500 mt-1">جلسه ثبت‌شده</p></div><div class="p-4 rounded-2xl bg-gray-50 dark:bg-gray-800/60"><b>{{store.completedTasksCount}}</b><p class="text-xs text-gray-500 mt-1">کار تکمیل‌شده</p></div><div class="p-4 rounded-2xl bg-gray-50 dark:bg-gray-800/60"><b>{{store.focusAverageMinutes}}د</b><p class="text-xs text-gray-500 mt-1">میانگین جلسه</p></div><div class="p-4 rounded-2xl bg-gray-50 dark:bg-gray-800/60"><b>{{completedToday}}/{{plannedToday}}</b><p class="text-xs text-gray-500 mt-1">اجرای امروز</p></div></div></UCard></div></template>
